INSERT INTO projects SET `id` = 1, `slug` = 'ralph-de-vinca-perfumery', `name` = 'Ralph de Vinca Perfumery', `division` = 'perfumery', `position` = 1, `summary` = 'A fragrance platform built before anyone asked for it.', `index_summary` = 'A fragrance platform built before anyone asked for it.', `meta_label` = 'Perfumery', `facts` = '[{\"label\":\"Division\",\"value\":\"Perfumery\"},{\"label\":\"Role\",\"value\":\"Design and development\"},{\"label\":\"Status\",\"value\":\"Live, ongoing\"}]', `situation` = 'Nobody asked for this to be fixed. It was built because the problem was irritating.\n\nFragrance information online is mostly either marketing copy written by the brands or unstructured opinion in forums. Someone trying to learn what a chypre is, or why an iris note behaves differently in two different houses, has to assemble the answer out of fragments.', `constraint_text` = 'No client, no deadline, and no revenue. That sounds like freedom, but it is its own constraint: nothing external forces a decision, and nothing stops the scope from growing forever. Discipline had to come from inside the project.', `result` = 'A working platform covering houses, fragrances, and notes, with a separate education section. It has no revenue and was never intended to have any yet.\n\nWhat it produced instead is the standard everything else in the group is measured against, and indirectly the work that came after it.', `decisions` = '[{\"body\":\"The data model for houses, fragrances, and notes was designed first, and content was added into it afterward. The opposite order (writing pages and normalising later) is why most sites like this never grow past a few dozen entries.\",\"title\":\"Structure before volume.\"},{\"body\":\"Ranking is what turns an information site into a sales channel. Leaving it out costs engagement and protects the one thing that makes the site worth visiting.\",\"title\":\"No rankings.\"},{\"body\":\"Academy sits apart from the browsing experience. Someone arriving to look one thing up and someone arriving to learn need differently shaped pages, and merging them serves neither.\",\"title\":\"Education kept separate from the catalogue.\"}]', `composition_top` = 'Blade · Tailwind CSS', `composition_heart` = 'Laravel · PHP', `composition_base` = 'MySQL', `images` = '[{\"alt\":\"\",\"path\":\"1/ab96b8ac-bd2a-4b4e-af8c-5b251416ceae.png\"}]', `cover` = 0, `seo_title` = NULL, `seo_description` = 'A fragrance platform built with no client and no deadline, and the decisions that kept it in scope.';
INSERT INTO projects SET `id` = 2, `slug` = 'bali-cebelok-gesiuh', `name` = 'Bali Cebelok Gesiuh', `division` = 'technology', `position` = 2, `summary` = 'A booking platform for a traditional coconut oil experience.', `index_summary` = 'A booking platform for a traditional coconut oil experience. The first paid work.', `meta_label` = 'Technology · Two weeks', `facts` = '[{\"label\":\"Division\",\"value\":\"Technology\"},{\"label\":\"Role\",\"value\":\"Design and development\"},{\"label\":\"Duration\",\"value\":\"Two weeks\"}]', `situation` = 'A traditional coconut oil practice, passed down through generations, with no way for a visitor to find it or book it. The knowledge existed. The path to it did not.', `constraint_text` = 'Two weeks, and a first client. A first client is a particular kind of pressure. The scope has to be clear enough that nobody ends up disappointed, and the result has to keep working without ongoing help.', `result` = 'A live platform that introduces the experience and takes bookings. First paid work, delivered in two weeks.', `decisions` = '[{\"body\":\"A visitor who does not understand what cebelok gesiuh is will not book it. The page explains first and asks second.\",\"title\":\"Story before booking.\"},{\"body\":\"No menu of options and no branching. Bookings for a traditional experience usually come from people who have just discovered it exists, and choice at that moment produces hesitation rather than confidence.\",\"title\":\"One path through the page.\"},{\"body\":\"The owner is not technical. Anything that would need regular changing was kept out of places that require a developer to reach.\",\"title\":\"Built to be handed over.\"}]', `composition_top` = 'Blade · Tailwind CSS', `composition_heart` = 'Laravel · PHP', `composition_base` = 'MySQL', `images` = '[]', `cover` = 0, `seo_title` = NULL, `seo_description` = 'A booking platform for a traditional Balinese coconut oil experience, delivered in two weeks.';
INSERT INTO projects SET `id` = 3, `slug` = 'pkkmb-instiki', `name` = 'PKKMB INSTIKI 2026', `division` = 'technology', `position` = 3, `summary` = 'A centralised attendance system for a campus orientation.', `index_summary` = 'An attendance system for a campus orientation, built in the time that was left.', `meta_label` = 'Technology · One week', `facts` = '[{\"label\":\"Division\",\"value\":\"Technology\"},{\"label\":\"Role\",\"value\":\"Design and development\"},{\"label\":\"Duration\",\"value\":\"One week\"}]', `situation` = 'PKKMB is a campus orientation involving hundreds of students, spread across many classes and sessions over several days. Attendance was recorded on paper and reconciled by hand afterward: slow while it was happening, and slower once it was over.', `constraint_text` = 'The committee began work on 20 August. The event started on 4 September. Fifteen days, and the system had to be correct on the first morning, because there is no second attempt at an orientation week.', `result` = 'A centralised system managing students, classes, attendance sessions, and administrative roles, used across the event. Paper recording and the manual reconciliation that followed it were removed.', `decisions` = '[{\"body\":\"Two roles, admin and session PJ, were defined before any screen was designed. Access rules retrofitted onto a finished interface are where systems like this usually break.\",\"title\":\"Roles before features.\"},{\"body\":\"The obvious design asks a PJ to choose a session before doing anything. In a crowded hall with students waiting, an extra navigation step is a real cost. The selector was removed for PJs and kept for admins, who genuinely need it.\",\"title\":\"Session PJs see every session at once.\"},{\"body\":\"Marking is done live rather than typed up later. This removes the reconciliation step entirely, which was the slowest part of the old process.\",\"title\":\"Attendance recorded as it happens.\"},{\"body\":\"With no time for thorough manual checking, the role-based rules were covered by tests. Those rules are where a mistake would do the most damage and be the hardest to notice.\",\"title\":\"Automated tests on the access rules.\"}]', `composition_top` = 'Blade · Tailwind CSS', `composition_heart` = 'Laravel · PHP', `composition_base` = 'MySQL', `images` = '[]', `cover` = 0, `seo_title` = NULL, `seo_description` = 'A centralised attendance system for a campus orientation, built in the fifteen days available.';
